CREATE TABLE IF NOT EXISTS adocao_organizacoes(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,whatsapp TEXT NOT NULL,cidade TEXT NOT NULL,estado TEXT,status TEXT NOT NULL DEFAULT 'ativo',codigo_hash TEXT NOT NULL UNIQUE,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS adocao_pets(id INTEGER PRIMARY KEY AUTOINCREMENT,organizacao_id INTEGER NOT NULL,nome TEXT NOT NULL,especie TEXT NOT NULL,porte TEXT NOT NULL,idade_faixa TEXT NOT NULL,sexo TEXT,convivencia TEXT,foto_url TEXT NOT NULL,video_url TEXT,historia TEXT,saude TEXT,cidade TEXT NOT NULL,estado TEXT,status TEXT NOT NULL DEFAULT 'disponivel',criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_adocao_busca ON adocao_pets(status,especie,porte,cidade);
